mapper.select:
select dsi.* from  dete_set_info dsi where dsi.state !='1'

    and dsi.name like
    '%'||#{name}||'%'
    concat('%',#{name},'%')
    concat('%',#{name},'%')


    and dsi.type_id= #{typeId}

and ( (dsi.view_level='1' and dsi.id in(select pmi.type_id from permission_info pmi, (SELECT ug.group_id FROM user_usergroup ug WHERE ug.user_id = #{user}) uug where pmi.view_level='1' and pmi.type='2' and pmi.rel_id=uug.group_id))
or (dsi.view_level='2' and dsi.id in (select pmi.type_id from permission_info pmi where pmi.view_level='2' and pmi.rel_id=#{system}))
or (dsi.view_level='3') )

    order by #{sidx}


        #{order}



limit #{start},#{pageSize}
